    if (canvas) { canvas.width = w; canvas.height = h; }
    stars = [];
    for (let i = 0; i < 100; i++) {
        stars.push({
            x: Math.random() * w - w/2,
            y: Math.random() * h - h/2,
            z: Math.random() * w
        });
    }
}

function render() {
    if (!ctx) return;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.25)';
    ctx.fillRect(0, 0, w, h);

    ctx.fillStyle = '#ffffff';
    for (let s of stars) {
        s.z -= 1.5;
        if (s.z <= 0) s.z = w;
        let px = (s.x / s.z) * (w / 2) + w/2;
        let py = (s.y / s.z) * (h / 2) + h/2;
        if (px < 0 || px > w || py < 0 || py > h) s.z = w;
        let size = (1 - s.z / w) * 3;
        ctx.fillRect(px, py, size, size);
    }
    requestAnimationFrame(render);
}

