function compile(type, src) {
	var s = gl.createShader(type);
	gl.shaderSource(s, src);
	gl.compileShader(s);
	if (!gl.getShaderParameter(s, gl.COMPILE_STATUS))
		throw new Error(gl.getShaderInfoLog(s));
	return s;
}

function initGL() {
	var vs = compile(gl.VERTEX_SHADER, VERT);
	var fs = compile(gl.FRAGMENT_SHADER, FRAG);
	program = gl.createProgram();
	gl.attachShader(program, vs);
	gl.attachShader(program, fs);
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS))
		throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	var buf = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buf);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	var a = gl.getAttribLocation(program, 'a_pos');
	gl.enableVertexAttribArray(a);
	gl.vertexAttribPointer(a, 2, gl.FLOAT, false, 0, 0);
	uTime = gl.getUniformLocation(program, 'u_time');
	uRes = gl.getUniformLocation(program, 'u_res');
	uFish = gl.getUniformLocation(program, 'u_fish[0]');
	uRipples = gl.getUniformLocation(program, 'u_ripples[0]');
	t0 = performance.now() / 1000;
}

function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }

function pickWaypoint(f) {
	f.wx = 0.12 + Math.random() * (aspect - 0.24);
	f.wy = 0.12 + Math.random() * 0.76;
}

function initFish() {
	fish = [];
	for (var i = 0; i < FISH_COUNT; i++) {
		var f = {
			x: 0.2 + Math.random() * (aspect - 0.4),
			y: 0.15 + Math.random() * 0.7,
			vx: 0.02, vy: 0.0,
			phase: Math.random() * 6.28,
			wx: 0, wy: 0
		};
		pickWaypoint(f);
		fish.push(f);
	}
}

function initRipples() {
	ripples = [];
	for (var i = 0; i < MAX_RIPPLES; i++) ripples.push({ x: 0, y: 0, age: -1 });
	for (var j = 0; j < MAX_RIPPLES * 3; j++) rippleData[j] = -1;
}

function addRipple(x, y) {
	var oldest = 0, oldestAge = -2;
	for (var i = 0; i < MAX_RIPPLES; i++) {
		if (ripples[i].age < 0) { oldest = i; break; }
		if (ripples[i].age > oldestAge) { oldestAge = ripples[i].age; oldest = i; }
	}
	ripples[oldest].x = x;
	ripples[oldest].y = y;
	ripples[oldest].age = 0;
}

function scare(x, y) {
	for (var i = 0; i < FISH_COUNT; i++) {
		var f = fish[i];
		var dx = f.x - x, dy = f.y - y;
		var d = Math.sqrt(dx * dx + dy * dy) || 0.0001;
		var imp = SCARE_FORCE * Math.exp(-d * 4.0);
		f.vx += dx / d * imp;
		f.vy += dy / d * imp;
	}
}

function updateFish(dt, now) {
	for (var i = 0; i < FISH_COUNT; i++) {
		var f = fish[i];
		var tx = f.wx, ty = f.wy;
		if (now - mouse.last < 3.0) {
			var mdx = mouse.x - f.x, mdy = mouse.y - f.y;
			var md = Math.sqrt(mdx * mdx + mdy * mdy);
			if (md < MOUSE_LURE_RANGE && md > 0.13) { tx = mouse.x; ty = mouse.y; }
		}
		var dx = tx - f.x, dy = ty - f.y;
		var d = Math.sqrt(dx * dx + dy * dy) || 0.0001;
		if (d < 0.06) pickWaypoint(f);
		var sp = FISH_SPEED * (0.8 + 0.4 * Math.sin(f.phase * 0.13 + i * 2.1));
		var k = Math.min(1, dt * 1.2);
		f.vx += (dx / d * sp - f.vx) * k;
		f.vy += (dy / d * sp - f.vy) * k;
		f.x = clamp(f.x + f.vx * dt, 0.05, aspect - 0.05);
		f.y = clamp(f.y + f.vy * dt, 0.06, 0.94);
		var spd = Math.sqrt(f.vx * f.vx + f.vy * f.vy);
		f.phase += dt * (3.0 + spd * 45.0);
		fishData[i * 4] = f.x;
		fishData[i * 4 + 1] = f.y;
		fishData[i * 4 + 2] = Math.atan2(f.vy, f.vx);
		fishData[i * 4 + 3] = f.phase;
	}
}

function updateRipples(dt) {
	for (var i = 0; i < MAX_RIPPLES; i++) {
		var r = ripples[i];
		if (r.age >= 0) {
			r.age += dt;
			if (r.age > 3.2) r.age = -1;
		}
		rippleData[i * 3] = r.x;
		rippleData[i * 3 + 1] = r.y;
		rippleData[i * 3 + 2] = r.age;
	}
}

function render() {
	var now = performance.now() / 1000;
	var dt = lastT ? Math.min(now - lastT, 0.1) : 0.016;
	lastT = now;
	updateFish(dt, now);
	updateRipples(dt);
	if (now > nextDimple) {
		var f = fish[Math.floor(Math.random() * FISH_COUNT)];
		addRipple(f.x, f.y);
		nextDimple = now + 5 + Math.random() * 9;
	}
	gl.viewport(0, 0, w, h);
	gl.uniform1f(uTime, now - t0);
	gl.uniform2f(uRes, w, h);
	gl.uniform4fv(uFish, fishData);
	gl.uniform3fv(uRipples, rippleData);
	gl.drawArrays(gl.TRIANGLES, 0, 3);
	requestAnimationFrame(render);
}

function sceneX(px) { return px / h; }
function sceneY(py) { return 1.0 - py / h; }

self.onmessage = function (e) {
	switch (e.data.type) {
		case 'init':
			canvas = e.data.canvas;
			w = e.data.width; h = e.data.height;
			canvas.width = w; canvas.height = h;
			aspect = w / h;
			gl = canvas.getContext('webgl2') || canvas.getContext('webgl');
			if (!gl) {
				var c2 = canvas.getContext('2d');
				if (c2) {
					c2.fillStyle = '#04141a';
					c2.fillRect(0, 0, w, h);
					c2.fillStyle = '#ff4466';
					c2.font = '16px monospace';
					c2.textAlign = 'center';
					c2.fillText('WebGL not available', w / 2, h / 2);
				}
				return;
			}
			try {
				initGL();
				initFish();
				initRipples();
				nextDimple = performance.now() / 1000 + 4;
				render();
			} catch (err) {
				self.postMessage({ type: 'error', message: 'Koi Pond shader: ' + err.message });
			}
			break;

		case 'resize':
			w = e.data.width; h = e.data.height;
			canvas.width = w; canvas.height = h;
			aspect = w / h;
			break;

		case 'mousemove':
			mouse.x = sceneX(e.data.x);
			mouse.y = sceneY(e.data.y);
			mouse.last = performance.now() / 1000;
			break;

		case 'click':
			var cx = sceneX(e.data.x), cy = sceneY(e.data.y);
			addRipple(cx, cy);
			scare(cx, cy);
			break;
	}
};

